WITH recent_departments AS (SELECT *, LENGTH(location) AS location_length FROM departments WHERE location IN ('London', 'Tokyo', 'Berlin') AND location IN ('Chiang Mai', 'New York', 'Tokyo')), summary AS (SELECT CASE WHEN location IN ('Chiang Mai', 'Tokyo') THEN 'priority' ELSE 'other' END AS location_group, ROUND((100 * SUM(CASE WHEN location = 'New York' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_new_york, COUNT(budget) AS budget_count FROM recent_departments GROUP BY CASE WHEN location IN ('Chiang Mai', 'Tokyo') THEN 'priority' ELSE 'other' END) SELECT location_group, budget_count FROM summary ORDER BY 2 DESC;
